--
-- Name: app_accept_offer(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_accept_offer(p_offer_id text, p_note text) RETURNS TABLE(booking_id text, load_id text, driver_id text, agreed_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  offer      load_offers%ROWTYPE;
  the_load   loads%ROWTYPE;
  new_booking TEXT;
BEGIN
  SELECT * INTO offer FROM load_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Offer not found' USING ERRCODE = 'no_data_found';
  END IF;

  -- Lock the load before authorizing, so two shippers' clients accepting two
  -- offers on the same load serialize here instead of both proceeding.
  SELECT * INTO the_load FROM loads WHERE id = offer.load_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Load not found' USING ERRCODE = 'no_data_found';
  END IF;

  -- Definer functions run as the owner and bypass RLS, so authorization is
  -- explicit: only the shipper who posted the load, or an admin.
  IF NOT app_is_admin() AND the_load.shipper_id IS DISTINCT FROM app_current_shipper_id() THEN
    RAISE EXCEPTION 'Only the shipper who posted this load may accept offers on it'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF offer.status <> 'pending' THEN
    RAISE EXCEPTION 'Offer is % and can no longer be accepted', offer.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF offer.expires_at <= now() THEN
    UPDATE load_offers SET status = 'expired', responded_at = now() WHERE id = offer.id;
    RAISE EXCEPTION 'Offer has expired' USING ERRCODE = 'check_violation';
  END IF;

  IF the_load.status <> 'open' THEN
    RAISE EXCEPTION 'Load is % and can no longer be booked', the_load.status
      USING ERRCODE = 'check_violation';
  END IF;

  new_booking := 'BK-' || md5(random()::text || clock_timestamp()::text);

  INSERT INTO bookings (id, load_id, driver_id, status, agreed_rate_per_mile)
  VALUES (new_booking, offer.load_id, offer.driver_id, 'active', offer.offered_rate_per_mile);

  UPDATE loads SET status = 'booked' WHERE id = offer.load_id;

  UPDATE load_offers
     SET status = 'accepted', responded_at = now(),
         responded_by = app_current_user_id(), response_note = p_note
   WHERE id = offer.id;

  -- Everyone else who bid on this load is out; leaving them pending would show
  -- carriers a live offer on a load that is already gone.
  UPDATE load_offers
     SET status = 'declined', responded_at = now(),
         responded_by = app_current_user_id(),
         response_note = 'Load awarded to another carrier'
   WHERE load_id = offer.load_id AND id <> offer.id AND status = 'pending';

  PERFORM app_log_load_event(
    offer.load_id, new_booking, 'offer_accepted', the_load.status::TEXT, 'booked', p_note,
    NULL, NULL,
    jsonb_build_object('offer_id', offer.id,
                       'posted_rate', the_load.rate_per_mile,
                       'agreed_rate', offer.offered_rate_per_mile)
  );

  RETURN QUERY SELECT new_booking, offer.load_id, offer.driver_id, offer.offered_rate_per_mile;
END $$;


--
-- Name: app_change_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_change_password(p_user_id text, p_new_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF app_current_user_id() IS DISTINCT FROM p_user_id AND NOT app_is_admin() THEN
    RAISE EXCEPTION 'A password may only be changed by its owner'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  UPDATE users SET password_hash = p_new_hash, updated_at = now() WHERE id = p_user_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  UPDATE refresh_tokens
     SET revoked_at = now(), revoked_reason = 'password_change'
   WHERE user_id = p_user_id AND revoked_at IS NULL;

  RETURN TRUE;
END $$;


--
-- Name: app_consume_refresh_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_consume_refresh_token(p_token_hash text) RETURNS TABLE(user_id text, family_id text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  row_found refresh_tokens%ROWTYPE;
BEGIN
  SELECT * INTO row_found FROM refresh_tokens WHERE token_hash = p_token_hash FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::TEXT, NULL::TEXT, 'not_found'::TEXT;
    RETURN;
  END IF;

  IF row_found.used_at IS NOT NULL THEN
    UPDATE refresh_tokens
       SET revoked_at = COALESCE(revoked_at, now()),
           revoked_reason = COALESCE(revoked_reason, 'reuse_detected')
     WHERE family_id = row_found.family_id AND revoked_at IS NULL;
    RETURN QUERY SELECT row_found.user_id, row_found.family_id, 'reuse_detected'::TEXT;
    RETURN;
  END IF;

  IF row_found.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT row_found.user_id, row_found.family_id, 'revoked'::TEXT;
    RETURN;
  END IF;

  IF row_found.expires_at <= now() THEN
    RETURN QUERY SELECT row_found.user_id, row_found.family_id, 'expired'::TEXT;
    RETURN;
  END IF;

  UPDATE refresh_tokens SET used_at = now() WHERE id = row_found.id;
  RETURN QUERY SELECT row_found.user_id, row_found.family_id, 'ok'::TEXT;
END $$;


--
-- Name: app_create_password_reset(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_password_reset(p_email text, p_token_hash text, p_ttl_minutes integer, p_ip text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE target_id TEXT;
BEGIN
  SELECT id INTO target_id FROM users WHERE lower(email) = lower(p_email);
  IF target_id IS NULL THEN RETURN NULL; END IF;

  DELETE FROM password_reset_tokens WHERE expires_at < now() - INTERVAL '7 days';

  -- Only the newest request stays live, so an old link in an inbox stops working.
  UPDATE password_reset_tokens SET used_at = now()
   WHERE user_id = target_id AND used_at IS NULL;

  INSERT INTO password_reset_tokens (id, user_id, token_hash, expires_at, requested_ip)
  VALUES ('prt-' || md5(random()::text || clock_timestamp()::text), target_id, p_token_hash,
          now() + make_interval(mins => GREATEST(p_ttl_minutes, 1)), p_ip);

  RETURN target_id;
END $$;


