--
-- Name: app_issue_refresh_token(text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_issue_refresh_token(p_user_id text, p_token_hash text, p_ttl_days integer, p_family_id text, p_user_agent text, p_ip text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_id     TEXT := 'rt-' || md5(random()::text || clock_timestamp()::text);
  the_family TEXT := COALESCE(p_family_id, 'fam-' || md5(random()::text || clock_timestamp()::text));
BEGIN
  -- Housekeeping: expired and long-revoked rows have no forensic value.
  DELETE FROM refresh_tokens
  WHERE expires_at < now() - INTERVAL '30 days'
     OR (revoked_at IS NOT NULL AND revoked_at < now() - INTERVAL '30 days');

  INSERT INTO refresh_tokens (id, user_id, token_hash, family_id, expires_at, user_agent, ip_address)
  VALUES (new_id, p_user_id, p_token_hash, the_family,
          now() + make_interval(days => GREATEST(p_ttl_days, 1)), p_user_agent, p_ip);

  RETURN new_id || '|' || the_family;
END $$;


--
-- Name: app_list_sessions(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_sessions(p_user_id text) RETURNS TABLE(id text, issued_at timestamp with time zone, expires_at timestamp with time zone, used_at timestamp with time zone, revoked_at timestamp with time zone, user_agent text, ip_address text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT id, issued_at, expires_at, used_at, revoked_at, user_agent, ip_address
  FROM refresh_tokens
  WHERE user_id = p_user_id
  ORDER BY issued_at DESC
  LIMIT 50
$$;


