--
-- Name: app_login_lockout_seconds(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_login_lockout_seconds(p_email text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  max_failures CONSTANT INTEGER := 5;
  window_secs  CONSTANT INTEGER := 900;   -- 15 minutes
  failures     INTEGER;
  newest       TIMESTAMP WITH TIME ZONE;
BEGIN
  SELECT count(*), max(attempted_at) INTO failures, newest
  FROM auth_login_attempts
  WHERE lower(email) = lower(p_email)
    AND NOT succeeded
    AND attempted_at > now() - make_interval(secs => window_secs);

  IF failures >= max_failures THEN
    RETURN GREATEST(0, window_secs - EXTRACT(EPOCH FROM (now() - newest))::INTEGER);
  END IF;
  RETURN 0;
END $$;


--
-- Name: app_notify(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_notify(p_user_id text, p_type text, p_title text, p_body text, p_link text, p_load_id text, p_severity text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_id TEXT;
  wants  BOOLEAN := TRUE;
  prefs  notification_preferences%ROWTYPE;
BEGIN
  IF p_user_id IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO prefs FROM notification_preferences WHERE user_id = p_user_id;
  IF FOUND THEN
    wants := CASE
      WHEN p_type LIKE 'offer%'        THEN prefs.offer_alerts
      WHEN p_type LIKE 'booking%'      THEN prefs.booking_alerts
      WHEN p_type LIKE 'load%'         THEN prefs.booking_alerts
      WHEN p_type LIKE 'settlement%'   THEN prefs.settlement_alerts
      WHEN p_type LIKE 'verification%' THEN prefs.verification_alerts
      WHEN p_type LIKE 'dispute%'      THEN prefs.dispute_alerts
      ELSE TRUE
    END;
  END IF;

  IF NOT wants THEN RETURN NULL; END IF;

  new_id := 'ntf-' || md5(random()::text || clock_timestamp()::text);
  INSERT INTO notifications (id, user_id, type, title, body, link, load_id, severity)
  VALUES (new_id, p_user_id, p_type, p_title, p_body, p_link, p_load_id,
          COALESCE(p_severity, 'info'));
  RETURN new_id;
END $$;


--
-- Name: app_rate_limit_hit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_rate_limit_hit(p_bucket text, p_limit integer, p_window_secs integer) RETURNS TABLE(allowed boolean, remaining integer, retry_after integer, window_reset timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  win_start TIMESTAMPTZ;
  current_hits INTEGER;
BEGIN
  -- Truncate now() onto a window boundary so every instance agrees on which
  -- window a request belongs to without coordinating.
  win_start := to_timestamp(floor(extract(epoch FROM now()) / p_window_secs) * p_window_secs);

  IF random() < 0.01 THEN
    DELETE FROM api_rate_limits WHERE window_start < now() - INTERVAL '1 hour';
  END IF;

  INSERT INTO api_rate_limits (bucket, window_start, hits)
  VALUES (p_bucket, win_start, 1)
  ON CONFLICT (bucket, window_start) DO UPDATE SET hits = api_rate_limits.hits + 1
  RETURNING api_rate_limits.hits INTO current_hits;

  RETURN QUERY SELECT
    current_hits <= p_limit,
    GREATEST(0, p_limit - current_hits),
    CASE WHEN current_hits <= p_limit THEN 0
         ELSE GREATEST(1, CEIL(EXTRACT(EPOCH FROM (win_start + make_interval(secs => p_window_secs) - now())))::INTEGER)
    END,
    win_start + make_interval(secs => p_window_secs);
END $$;


--
-- Name: app_record_login_attempt(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_record_login_attempt(p_email text, p_ip text, p_ok boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO auth_login_attempts (email, ip_address, succeeded)
  VALUES (lower(p_email), p_ip, p_ok);

  -- On success, clear the failure streak for that account.
  IF p_ok THEN
    DELETE FROM auth_login_attempts
    WHERE lower(email) = lower(p_email) AND NOT succeeded;
  END IF;

  -- Keep the table bounded.
  DELETE FROM auth_login_attempts WHERE attempted_at < now() - INTERVAL '7 days';
END $$;


--
-- Name: app_reset_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_reset_password(p_token_hash text, p_new_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE target_id TEXT;
BEGIN
  SELECT user_id INTO target_id
  FROM password_reset_tokens
  WHERE token_hash = p_token_hash AND used_at IS NULL AND expires_at > now()
  FOR UPDATE;

  IF target_id IS NULL THEN RETURN NULL; END IF;

  UPDATE password_reset_tokens SET used_at = now() WHERE token_hash = p_token_hash;
  UPDATE users SET password_hash = p_new_hash, updated_at = now() WHERE id = target_id;

  -- Every session predating the reset dies with the old password.
  UPDATE refresh_tokens
     SET revoked_at = now(), revoked_reason = 'password_reset'
   WHERE user_id = target_id AND revoked_at IS NULL;

  RETURN target_id;
END $$;


--
-- Name: app_resolve_dispute(text, public.dispute_status, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_resolve_dispute(p_dispute_id text, p_status public.dispute_status, p_note text, p_adjustment numeric) RETURNS TABLE(dispute_id text, status public.dispute_status, adjustment_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  dsp    settlement_disputes%ROWTYPE;
  adj_id TEXT;
BEGIN
  IF NOT app_is_admin() THEN
    RAISE EXCEPTION 'Only an administrator may resolve a dispute'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_status NOT IN ('under_review', 'resolved', 'rejected') THEN
    RAISE EXCEPTION 'A dispute can only move to under_review, resolved or rejected'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO dsp FROM settlement_disputes WHERE id = p_dispute_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dispute not found' USING ERRCODE = 'no_data_found';
  END IF;

  IF dsp.status IN ('resolved', 'rejected') THEN
    RAISE EXCEPTION 'Dispute is already %', dsp.status USING ERRCODE = 'check_violation';
  END IF;

  IF p_adjustment IS NOT NULL AND p_adjustment <> 0 THEN
    IF p_status <> 'resolved' THEN
      RAISE EXCEPTION 'An adjustment can only accompany a resolved dispute'
        USING ERRCODE = 'check_violation';
    END IF;
    adj_id := 'adj-' || md5(random()::text || clock_timestamp()::text);
    INSERT INTO settlement_adjustments (id, settlement_id, dispute_id, amount, reason, created_by)
    VALUES (adj_id, dsp.settlement_id, dsp.id, p_adjustment,
            COALESCE(p_note, 'Dispute resolution'), app_current_user_id());
  END IF;

  UPDATE settlement_disputes
     SET status = p_status,
         resolution_note = p_note,
         resolved_at = CASE WHEN p_status IN ('resolved', 'rejected') THEN now() ELSE NULL END,
         resolved_by = CASE WHEN p_status IN ('resolved', 'rejected') THEN app_current_user_id() ELSE NULL END,
         updated_at = now()
   WHERE id = p_dispute_id;

  PERFORM app_log_load_event(
    dsp.load_id, NULL,
    CASE WHEN p_status = 'under_review' THEN 'disputed' ELSE 'dispute_resolved' END::load_event_type,
    dsp.status::TEXT, p_status::TEXT, p_note, NULL, NULL,
    jsonb_build_object('dispute_id', dsp.id, 'adjustment', COALESCE(p_adjustment, 0))
  );

  PERFORM app_notify(dsp.opened_by_user_id, 'dispute_' || p_status::TEXT,
    'Dispute ' || p_status::TEXT, COALESCE(p_note, ''),
    '/settlements/' || dsp.settlement_id, dsp.load_id,
    CASE p_status WHEN 'resolved' THEN 'success' WHEN 'rejected' THEN 'warning' ELSE 'info' END);

  RETURN QUERY SELECT dsp.id, p_status, adj_id;
END $$;


--
-- Name: app_review_driver_document(text, public.verification_status, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_review_driver_document(p_document_id text, p_decision public.verification_status, p_notes text) RETURNS TABLE(driver_id text, document_status public.verification_status, driver_status public.verification_status)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  doc            driver_documents%ROWTYPE;
  rolled_up      verification_status;
  has_rejected   BOOLEAN;
  pending_count  INTEGER;
  verified_types INTEGER;
BEGIN
  IF NOT app_is_admin() THEN
    RAISE EXCEPTION 'Only an administrator may review carrier documents'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO doc FROM driver_documents WHERE id = p_document_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Document not found' USING ERRCODE = 'no_data_found';
  END IF;

  UPDATE driver_documents
     SET review_status = p_decision,
         verified      = (p_decision = 'verified'),
         reviewed_at   = now(),
         reviewed_by   = app_current_user_id(),
         review_notes  = p_notes
   WHERE id = p_document_id;

  INSERT INTO verification_reviews (id, driver_id, document_id, reviewer_user_id, decision, notes)
  VALUES ('vrv-' || md5(random()::text || clock_timestamp()::text),
          doc.driver_id, p_document_id, app_current_user_id(), p_decision, p_notes);

  SELECT
    bool_or(review_status = 'rejected'),
    count(*) FILTER (WHERE review_status = 'pending'),
    count(DISTINCT doc_type) FILTER (WHERE review_status = 'verified' AND doc_type <> 'pod')
  INTO has_rejected, pending_count, verified_types
  FROM driver_documents WHERE driver_documents.driver_id = doc.driver_id;

  rolled_up := CASE
    WHEN has_rejected THEN 'rejected'
    WHEN pending_count > 0 THEN 'pending'
    -- CDL, operating authority and a certificate of insurance: the three
    -- documents a shipper is entitled to assume exist.
    WHEN verified_types >= 3 THEN 'verified'
    ELSE 'pending'
  END::verification_status;

  UPDATE driver_profiles
     SET verification_status = rolled_up,
         verified_at = CASE WHEN rolled_up = 'verified' THEN now() ELSE NULL END,
         verified_by = CASE WHEN rolled_up = 'verified' THEN app_current_user_id() ELSE NULL END,
         rejection_reason = CASE WHEN rolled_up = 'rejected' THEN p_notes ELSE NULL END
   WHERE id = doc.driver_id;

  PERFORM app_notify(
    (SELECT user_id FROM driver_profiles WHERE id = doc.driver_id),
    'verification_' || rolled_up::TEXT,
    'Carrier verification ' || rolled_up::TEXT,
    COALESCE(p_notes, ''), '/onboarding', NULL,
    CASE rolled_up WHEN 'verified' THEN 'success' WHEN 'rejected' THEN 'critical' ELSE 'info' END
  );

  RETURN QUERY SELECT doc.driver_id, p_decision, rolled_up;
END $$;


--
-- Name: app_revoke_refresh_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_refresh_token(p_token_hash text, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE affected INTEGER;
BEGIN
  UPDATE refresh_tokens
     SET revoked_at = now(), revoked_reason = COALESCE(p_reason, 'logout')
   WHERE token_hash = p_token_hash AND revoked_at IS NULL;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END $$;


--
-- Name: app_revoke_user_sessions(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_user_sessions(p_user_id text, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE affected INTEGER;
BEGIN
  UPDATE refresh_tokens
     SET revoked_at = now(), revoked_reason = COALESCE(p_reason, 'revoke_all')
   WHERE user_id = p_user_id AND revoked_at IS NULL;
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END $$;


--
-- Name: app_set_driver_verification(text, public.verification_status, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_driver_verification(p_driver_id text, p_status public.verification_status, p_reason text) RETURNS public.verification_status
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT app_is_admin() THEN
    RAISE EXCEPTION 'Only an administrator may set carrier verification'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  UPDATE driver_profiles
     SET verification_status = p_status,
         verified_at = CASE WHEN p_status = 'verified' THEN now() ELSE NULL END,
         verified_by = CASE WHEN p_status = 'verified' THEN app_current_user_id() ELSE NULL END,
         rejection_reason = CASE WHEN p_status = 'rejected' THEN p_reason ELSE NULL END
   WHERE id = p_driver_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Carrier not found' USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO verification_reviews (id, driver_id, document_id, reviewer_user_id, decision, notes)
  VALUES ('vrv-' || md5(random()::text || clock_timestamp()::text),
          p_driver_id, NULL, app_current_user_id(), p_status, p_reason);

  PERFORM app_notify(
    (SELECT user_id FROM driver_profiles WHERE id = p_driver_id),
    'verification_' || p_status::TEXT,
    'Carrier verification ' || p_status::TEXT,
    COALESCE(p_reason, ''), '/onboarding', NULL,
    CASE p_status WHEN 'verified' THEN 'success' WHEN 'rejected' THEN 'critical' ELSE 'info' END
  );

  RETURN p_status;
END $$;


--
-- Name: audit_row_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  redacted_old JSONB;
  redacted_new JSONB;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    redacted_old := to_jsonb(OLD) - 'password_hash' - 'processor_account_id'
                    - 'token_hash' - 'response_body';
  END IF;
  IF TG_OP <> 'DELETE' THEN
    redacted_new := to_jsonb(NEW) - 'password_hash' - 'processor_account_id'
                    - 'token_hash' - 'response_body';
  END IF;

  INSERT INTO audit_log (table_name, operation, row_id, actor_id, actor_role, old_data, new_data)
  VALUES (
    TG_TABLE_NAME,
    TG_OP,
    COALESCE(redacted_new ->> 'id', redacted_old ->> 'id',
             redacted_new ->> 'key', redacted_old ->> 'key'),
    app_current_user_id(),
    app_current_role(),
    redacted_old,
    redacted_new
  );

  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: bookings_release_load(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_release_load() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status <> 'cancelled' THEN
    NEW.cancelled_at := COALESCE(NEW.cancelled_at, now());

    -- A delivered load has already settled; releasing it would contradict the
    -- ledger, so a settled booking cannot be cancelled at all.
    IF EXISTS (SELECT 1 FROM settlements s WHERE s.booking_id = NEW.id) THEN
      RAISE EXCEPTION 'Booking % has settled and cannot be cancelled', NEW.id
        USING ERRCODE = 'restrict_violation';
    END IF;

    UPDATE loads SET status = 'open'
     WHERE id = NEW.load_id AND status IN ('booked', 'in_transit');
  END IF;

  IF NEW.picked_up_at IS NOT NULL AND OLD.picked_up_at IS NULL THEN
    UPDATE loads SET status = 'in_transit'
     WHERE id = NEW.load_id AND status = 'booked';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: driver_verification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.driver_verification_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.verification_status IS DISTINCT FROM OLD.verification_status
     AND NOT app_is_admin()
     AND app_current_role() <> 'enrollment' THEN
    RAISE EXCEPTION 'verification_status is set by review, not by the carrier'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: forbid_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only: % is not permitted', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: loads_status_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loads_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();

  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'delivered' THEN
    RAISE EXCEPTION 'Load % is delivered and cannot change status', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status = 'cancelled' THEN
    RAISE EXCEPTION 'Load % is cancelled and cannot be reopened', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT (
    (OLD.status = 'open'       AND NEW.status IN ('booked', 'cancelled')) OR
    (OLD.status = 'booked'     AND NEW.status IN ('in_transit', 'delivered', 'open', 'cancelled')) OR
    (OLD.status = 'in_transit' AND NEW.status IN ('delivered', 'cancelled'))
  ) THEN
    RAISE EXCEPTION 'Illegal load transition % -> % on %', OLD.status, NEW.status, OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'cancelled' THEN
    NEW.cancelled_at := COALESCE(NEW.cancelled_at, now());
    NEW.cancellation_reason := COALESCE(NEW.cancellation_reason, 'No reason supplied');
  END IF;

  RETURN NEW;
END $$;


--
-- Name: loads_timeline_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loads_timeline_writer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  evt load_event_type;
  bk  TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_log_load_event(NEW.id, NULL, 'posted', NULL, NEW.status::TEXT, NULL, NULL, NULL, NULL);
    RETURN NEW;
  END IF;

  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  evt := CASE NEW.status
           WHEN 'booked'     THEN 'booked'
           WHEN 'in_transit' THEN 'in_transit'
           WHEN 'delivered'  THEN 'delivered'
           WHEN 'cancelled'  THEN 'cancelled'
           ELSE 'updated'
         END::load_event_type;

  SELECT b.id INTO bk FROM bookings b
   WHERE b.load_id = NEW.id AND b.status <> 'cancelled'
   ORDER BY b.booked_at DESC LIMIT 1;

  PERFORM app_log_load_event(
    NEW.id, bk, evt, OLD.status::TEXT, NEW.status::TEXT,
    CASE WHEN NEW.status = 'cancelled' THEN NEW.cancellation_reason ELSE NULL END,
    NULL, NULL, NULL
  );
  RETURN NEW;
END $$;


--
-- Name: notify_on_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  shipper_user TEXT;
  driver_user  TEXT;
  driver_name  TEXT;
  lane         TEXT;
BEGIN
  SELECT sp.user_id, l.origin_city || ', ' || l.origin_state || ' → ' || l.dest_city || ', ' || l.dest_state
    INTO shipper_user, lane
  FROM loads l JOIN shipper_profiles sp ON sp.id = l.shipper_id
  WHERE l.id = NEW.load_id;

  SELECT d.user_id, d.full_name INTO driver_user, driver_name
  FROM driver_profiles d WHERE d.id = NEW.driver_id;

  IF TG_OP = 'INSERT' THEN
    PERFORM app_notify(shipper_user, 'booking_created', 'Your load was booked',
      COALESCE(driver_name, 'A carrier') || ' booked ' || COALESCE(lane, NEW.load_id),
      '/loads/' || NEW.load_id, NEW.load_id, 'success');
    RETURN NEW;
  END IF;

  IF NEW.status = 'cancelled' AND OLD.status <> 'cancelled' THEN
    PERFORM app_notify(shipper_user, 'booking_cancelled', 'A booking was cancelled',
      COALESCE(lane, NEW.load_id) || ' is back on the board',
      '/loads/' || NEW.load_id, NEW.load_id, 'warning');
    PERFORM app_notify(driver_user, 'booking_cancelled', 'Your booking was cancelled',
      COALESCE(NEW.cancellation_reason, 'No reason supplied'),
      '/loads/' || NEW.load_id, NEW.load_id, 'warning');
  END IF;

  IF NEW.picked_up_at IS NOT NULL AND OLD.picked_up_at IS NULL THEN
    PERFORM app_notify(shipper_user, 'load_picked_up', 'Load picked up',
      COALESCE(lane, NEW.load_id) || ' is in transit',
      '/loads/' || NEW.load_id, NEW.load_id, 'info');
  END IF;

  RETURN NEW;
END $$;


--
-- Name: notify_on_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  shipper_user TEXT;
  driver_user  TEXT;
  driver_name  TEXT;
BEGIN
  SELECT sp.user_id INTO shipper_user
  FROM loads l JOIN shipper_profiles sp ON sp.id = l.shipper_id
  WHERE l.id = NEW.load_id;

  SELECT d.user_id, d.full_name INTO driver_user, driver_name
  FROM driver_profiles d WHERE d.id = NEW.driver_id;

  IF TG_OP = 'INSERT' THEN
    PERFORM app_notify(shipper_user, 'offer_received', 'New rate offer',
      COALESCE(driver_name, 'A carrier') || ' offered $' ||
      to_char(NEW.offered_rate_per_mile, 'FM990.00') || '/mi',
      '/loads/' || NEW.load_id, NEW.load_id, 'info');
    RETURN NEW;
  END IF;

  IF NEW.status <> OLD.status AND NEW.status IN ('accepted', 'declined', 'expired') THEN
    PERFORM app_notify(driver_user, 'offer_' || NEW.status,
      'Your offer was ' || NEW.status,
      COALESCE(NEW.response_note, ''),
      '/loads/' || NEW.load_id, NEW.load_id,
      CASE NEW.status WHEN 'accepted' THEN 'success' ELSE 'info' END);
  END IF;

  RETURN NEW;
END $_$;


--
-- Name: notify_on_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  shipper_user TEXT;
  driver_user  TEXT;
BEGIN
  SELECT sp.user_id INTO shipper_user
  FROM loads l JOIN shipper_profiles sp ON sp.id = l.shipper_id
  WHERE l.id = NEW.load_id;

  SELECT d.user_id INTO driver_user
  FROM bookings b JOIN driver_profiles d ON d.id = b.driver_id
  WHERE b.id = NEW.booking_id;

  PERFORM app_notify(driver_user, 'settlement_paid', 'Settlement posted',
    'Net to you: $' || to_char(NEW.net_amount, 'FM999999990.00'),
    '/settlements/' || NEW.id, NEW.load_id, 'success');

  PERFORM app_notify(shipper_user, 'settlement_posted', 'Load delivered and settled',
    'Gross: $' || to_char(NEW.gross_amount, 'FM999999990.00'),
    '/settlements/' || NEW.id, NEW.load_id, 'success');

  RETURN NEW;
END $_$;


--
-- Name: ratings_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ratings_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM settlements s WHERE s.booking_id = NEW.booking_id) THEN
      RAISE EXCEPTION 'A load can only be rated once it has settled'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.booking_id       IS DISTINCT FROM OLD.booking_id
  OR NEW.rater_user_id    IS DISTINCT FROM OLD.rater_user_id
  OR NEW.subject_driver_id IS DISTINCT FROM OLD.subject_driver_id
  OR NEW.subject_shipper_id IS DISTINCT FROM OLD.subject_shipper_id THEN
    RAISE EXCEPTION 'A rating cannot be moved to a different load or party'
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.created_at < now() - INTERVAL '24 hours' THEN
    RAISE EXCEPTION 'Ratings can only be edited within 24 hours of being left'
      USING ERRCODE = 'check_violation';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: users_default_preferences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_default_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO notification_preferences (user_id) VALUES (NEW.id)
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
END $$;


