--
-- Name: settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.settlements (
    id text NOT NULL,
    booking_id text NOT NULL,
    load_id text NOT NULL,
    miles numeric NOT NULL,
    rate_per_mile numeric NOT NULL,
    fuel_rate_per_mile numeric DEFAULT 0.45 NOT NULL,
    gross_amount numeric NOT NULL,
    fee_amount numeric NOT NULL,
    fee_pct_applied numeric NOT NULL,
    fuel_cost numeric NOT NULL,
    factor_cost numeric DEFAULT 0 NOT NULL,
    factored boolean DEFAULT false,
    net_amount numeric NOT NULL,
    settled_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT settlements_fee_pct_sane CHECK (((fee_pct_applied >= (0)::numeric) AND (fee_pct_applied <= 0.5))),
    CONSTRAINT settlements_math_balances CHECK (((abs((net_amount - (((gross_amount - fee_amount) - fuel_cost) - factor_cost))) < 0.01) AND (abs((gross_amount - (miles * rate_per_mile))) < 0.01))),
    CONSTRAINT settlements_non_negative CHECK (((miles > (0)::numeric) AND (rate_per_mile > (0)::numeric) AND (gross_amount >= (0)::numeric) AND (fee_amount >= (0)::numeric) AND (fuel_cost >= (0)::numeric) AND (factor_cost >= (0)::numeric)))
);


--
-- Name: driver_earnings_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.driver_earnings_view AS
 SELECT d.id AS driver_id,
    d.full_name,
    (count(s.id))::integer AS loads_settled,
    COALESCE(sum(s.miles), (0)::numeric) AS miles,
    COALESCE(sum(s.gross_amount), (0)::numeric) AS gross,
    COALESCE(sum(s.fee_amount), (0)::numeric) AS platform_fees,
    COALESCE(sum(s.fuel_cost), (0)::numeric) AS fuel,
    COALESCE(sum(s.factor_cost), (0)::numeric) AS quick_pay_cost,
    COALESCE(sum(s.net_amount), (0)::numeric) AS net,
    COALESCE(sum(adj.total), (0)::numeric) AS adjustments,
    (COALESCE(sum(s.net_amount), (0)::numeric) + COALESCE(sum(adj.total), (0)::numeric)) AS effective_net,
        CASE
            WHEN (COALESCE(sum(s.miles), (0)::numeric) > (0)::numeric) THEN round((sum(s.net_amount) / sum(s.miles)), 4)
            ELSE (0)::numeric
        END AS net_per_mile,
        CASE
            WHEN (COALESCE(sum(s.miles), (0)::numeric) > (0)::numeric) THEN round((sum(s.gross_amount) / sum(s.miles)), 4)
            ELSE (0)::numeric
        END AS gross_per_mile,
    min(s.settled_at) AS first_settled_at,
    max(s.settled_at) AS last_settled_at
   FROM (((public.driver_profiles d
     LEFT JOIN public.bookings b ON (((b.driver_id = d.id) AND (b.status = 'completed'::public.booking_status))))
     LEFT JOIN public.settlements s ON ((s.booking_id = b.id)))
     LEFT JOIN ( SELECT settlement_adjustments.settlement_id,
            sum(settlement_adjustments.amount) AS total
           FROM public.settlement_adjustments
          GROUP BY settlement_adjustments.settlement_id) adj ON ((adj.settlement_id = s.id)))
  WHERE (public.app_is_admin() OR (d.id = public.app_current_driver_id()))
  GROUP BY d.id, d.full_name;


