-- Name: driver_payment_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.driver_payment_accounts (
    id text NOT NULL,
    driver_id text NOT NULL,
    payment_processor text DEFAULT 'stripe'::text NOT NULL,
    processor_account_id text NOT NULL,
    same_day_funding_opt_in boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT payment_account_is_tokenized CHECK (((processor_account_id !~ '^[0-9-]{6,}$'::text) AND (length(processor_account_id) >= 8)))
);


--
-- Name: driver_performance_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.driver_performance_view AS
 SELECT d.id AS driver_id,
    (count(b.id))::integer AS bookings_total,
    (count(b.id) FILTER (WHERE (b.status = 'completed'::public.booking_status)))::integer AS bookings_completed,
    (count(b.id) FILTER (WHERE (b.status = 'cancelled'::public.booking_status)))::integer AS bookings_cancelled,
        CASE
            WHEN (count(b.id) > 0) THEN round((((count(b.id) FILTER (WHERE (b.status = 'completed'::public.booking_status)))::numeric / (count(b.id))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS completion_pct,
    round(avg((EXTRACT(epoch FROM (b.delivered_at - b.booked_at)) / 3600.0)), 1) AS avg_hours_to_deliver
   FROM (public.driver_profiles d
     LEFT JOIN public.bookings b ON ((b.driver_id = d.id)))
  GROUP BY d.id;


--
-- Name: ratings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ratings (
    id text NOT NULL,
    booking_id text NOT NULL,
    load_id text NOT NULL,
    rater_user_id text NOT NULL,
    rater_role text NOT NULL,
    subject_driver_id text,
    subject_shipper_id text,
    score integer NOT NULL,
    communication_score integer,
    on_time boolean,
    comment text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ratings_comment_check CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
    CONSTRAINT ratings_communication_score_check CHECK (((communication_score >= 1) AND (communication_score <= 5))),
    CONSTRAINT ratings_one_subject CHECK ((((subject_driver_id IS NOT NULL) AND (subject_shipper_id IS NULL)) OR ((subject_driver_id IS NULL) AND (subject_shipper_id IS NOT NULL)))),
    CONSTRAINT ratings_rater_role_check CHECK ((rater_role = ANY (ARRAY['driver'::text, 'shipper'::text]))),
    CONSTRAINT ratings_score_check CHECK (((score >= 1) AND (score <= 5)))
);


--
-- Name: driver_reputation_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.driver_reputation_view AS
 SELECT d.id AS driver_id,
    d.full_name,
    d.home_base_city,
    d.home_base_state,
    d.verification_status,
    (count(r.id))::integer AS rating_count,
    round(avg(r.score), 2) AS avg_score,
    round(avg(r.communication_score), 2) AS avg_communication,
    round((COALESCE(avg(
        CASE
            WHEN r.on_time THEN 1.0
            ELSE 0.0
        END), (0)::numeric) * (100)::numeric), 1) AS on_time_pct
   FROM (public.driver_profiles d
     LEFT JOIN public.ratings r ON ((r.subject_driver_id = d.id)))
  GROUP BY d.id, d.full_name, d.home_base_city, d.home_base_state, d.verification_status;


