CREATE TABLE public.loads (
    id text NOT NULL,
    shipper_id text NOT NULL,
    origin_city text NOT NULL,
    origin_state text NOT NULL,
    dest_city text NOT NULL,
    dest_state text NOT NULL,
    miles numeric NOT NULL,
    rate_per_mile numeric NOT NULL,
    equipment_type public.equipment_type DEFAULT 'dry_van'::public.equipment_type NOT NULL,
    pickup_date text NOT NULL,
    weight_lbs numeric,
    notes text,
    same_day_funding_offered boolean DEFAULT false,
    status public.load_status DEFAULT 'open'::public.load_status,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    delivery_date text,
    commodity text,
    reference_number text,
    cancelled_at timestamp with time zone,
    cancellation_reason text,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT loads_positive_amounts CHECK (((miles > (0)::numeric) AND (rate_per_mile > (0)::numeric) AND ((weight_lbs IS NULL) OR (weight_lbs >= (0)::numeric))))
);


--
-- Name: lane_rate_stats_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lane_rate_stats_view AS
 SELECT l.origin_state,
    l.dest_state,
    l.equipment_type,
    (count(*))::integer AS settlement_count,
    round(avg(s.rate_per_mile), 4) AS avg_rate_per_mile,
    round(min(s.rate_per_mile), 4) AS min_rate_per_mile,
    round(max(s.rate_per_mile), 4) AS max_rate_per_mile,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((s.rate_per_mile)::double precision)))::numeric, 4) AS median_rate_per_mile,
    round(avg(s.miles), 1) AS avg_miles,
    round(avg(s.net_amount), 2) AS avg_net_to_carrier,
    max(s.settled_at) AS last_settled_at
   FROM (public.settlements s
     JOIN public.loads l ON ((l.id = s.load_id)))
  GROUP BY l.origin_state, l.dest_state, l.equipment_type
 HAVING (count(*) >= 3);


--
-- Name: load_board_stats_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.load_board_stats_view AS
 SELECT (count(*) FILTER (WHERE (status = 'open'::public.load_status)))::integer AS open_loads,
    (count(*) FILTER (WHERE (status = 'booked'::public.load_status)))::integer AS booked_loads,
    (count(*) FILTER (WHERE (status = 'in_transit'::public.load_status)))::integer AS in_transit_loads,
    (count(*) FILTER (WHERE (status = 'delivered'::public.load_status)))::integer AS delivered_loads,
    (count(*) FILTER (WHERE (status = 'cancelled'::public.load_status)))::integer AS cancelled_loads,
    COALESCE(round(avg(rate_per_mile) FILTER (WHERE (status = 'open'::public.load_status)), 4), (0)::numeric) AS avg_open_rate_per_mile,
    COALESCE(sum(miles) FILTER (WHERE (status = 'open'::public.load_status)), (0)::numeric) AS open_miles,
    (count(DISTINCT shipper_id))::integer AS shippers_posting
   FROM public.loads;


