    resolved_by text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT settlement_disputes_category_check CHECK ((category = ANY (ARRAY['rate'::text, 'miles'::text, 'fuel'::text, 'detention'::text, 'damage'::text, 'fee'::text, 'other'::text]))),
    CONSTRAINT settlement_disputes_claimed_amount_check CHECK (((claimed_amount IS NULL) OR (claimed_amount >= (0)::numeric))),
    CONSTRAINT settlement_disputes_opened_by_role_check CHECK ((opened_by_role = ANY (ARRAY['driver'::text, 'shipper'::text, 'admin'::text]))),
    CONSTRAINT settlement_disputes_reason_check CHECK (((length(reason) >= 10) AND (length(reason) <= 4000)))
);


--
-- Name: settlement_effective_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.settlement_effective_view AS
 SELECT s.id,
    s.load_id,
    s.booking_id,
    l.origin_city,
    l.origin_state,
    l.dest_city,
    l.dest_state,
    l.equipment_type,
    s.miles,
    s.rate_per_mile,
    s.fuel_rate_per_mile,
    s.gross_amount,
    s.fee_amount,
    s.fee_pct_applied,
    s.fuel_cost,
    s.factor_cost,
    s.factored,
    s.net_amount AS original_net_amount,
    COALESCE(adj.total, (0)::numeric) AS adjustment_total,
    (s.net_amount + COALESCE(adj.total, (0)::numeric)) AS effective_net_amount,
    (COALESCE(adj.count, (0)::bigint))::integer AS adjustment_count,
    (COALESCE(dsp.open_count, (0)::bigint))::integer AS open_dispute_count,
    s.settled_at
   FROM (((public.settlements s
     JOIN public.loads l ON ((l.id = s.load_id)))
     LEFT JOIN ( SELECT settlement_adjustments.settlement_id,
            sum(settlement_adjustments.amount) AS total,
            count(*) AS count
           FROM public.settlement_adjustments
          GROUP BY settlement_adjustments.settlement_id) adj ON ((adj.settlement_id = s.id)))
     LEFT JOIN ( SELECT settlement_disputes.settlement_id,
            count(*) AS open_count
           FROM public.settlement_disputes
          WHERE (settlement_disputes.status = ANY (ARRAY['open'::public.dispute_status, 'under_review'::public.dispute_status]))
          GROUP BY settlement_disputes.settlement_id) dsp ON ((dsp.settlement_id = s.id)));


--
-- Name: settlement_totals_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.settlement_totals_view AS
 SELECT (count(*))::integer AS count,
    COALESCE(sum(miles), (0)::numeric) AS miles,
    COALESCE(sum(gross_amount), (0)::numeric) AS gross,
    COALESCE(sum(fee_amount), (0)::numeric) AS fee,
    COALESCE(sum(fuel_cost), (0)::numeric) AS fuel,
    COALESCE(sum(factor_cost), (0)::numeric) AS factor,
    COALESCE(sum(net_amount), (0)::numeric) AS net
   FROM public.settlements;


