-- Name: shipper_reputation_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.shipper_reputation_view AS
 SELECT s.id AS shipper_id,
    s.company_name,
    (count(r.id))::integer AS rating_count,
    round(avg(r.score), 2) AS avg_score,
    round(avg(r.communication_score), 2) AS avg_communication
   FROM (public.shipper_profiles s
     LEFT JOIN public.ratings r ON ((r.subject_shipper_id = s.id)))
  GROUP BY s.id, s.company_name;


--
-- Name: shipper_spend_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.shipper_spend_view AS
 SELECT sp.id AS shipper_id,
    sp.company_name,
    (count(DISTINCT l.id) FILTER (WHERE (l.status = 'open'::public.load_status)))::integer AS loads_open,
    (count(DISTINCT l.id) FILTER (WHERE (l.status = 'booked'::public.load_status)))::integer AS loads_booked,
    (count(DISTINCT l.id) FILTER (WHERE (l.status = 'in_transit'::public.load_status)))::integer AS loads_in_transit,
    (count(DISTINCT l.id) FILTER (WHERE (l.status = 'delivered'::public.load_status)))::integer AS loads_delivered,
    (count(DISTINCT l.id) FILTER (WHERE (l.status = 'cancelled'::public.load_status)))::integer AS loads_cancelled,
    (count(s.id))::integer AS loads_settled,
    COALESCE(sum(s.gross_amount), (0)::numeric) AS spend_gross,
    COALESCE(sum(s.miles), (0)::numeric) AS miles,
        CASE
            WHEN (COALESCE(sum(s.miles), (0)::numeric) > (0)::numeric) THEN round((sum(s.gross_amount) / sum(s.miles)), 4)
            ELSE (0)::numeric
        END AS avg_rate_per_mile,
    max(s.settled_at) AS last_settled_at
   FROM ((public.shipper_profiles sp
     LEFT JOIN public.loads l ON ((l.shipper_id = sp.id)))
     LEFT JOIN public.settlements s ON ((s.load_id = l.id)))
  WHERE (public.app_is_admin() OR (sp.id = public.app_current_shipper_id()))
  GROUP BY sp.id, sp.company_name;


